. "$PSScriptRoot\Common.ps1"; . "$PSScriptRoot\Network.ps1"
function Get-ReleaseInfo([string]$Service) { $s=Resolve-CPAService $Service; $repo=if($s -eq 'cli-proxy-api'){'router-for-me/CLIProxyAPI'}else{'Willxup/cpa-usage-keeper'}; $file=Join-Path (Get-CPAStackRoot) "downloads\$s.json"; New-Item -ItemType Directory -Force (Split-Path $file)|Out-Null; Invoke-CPAStackWeb "https://api.github.com/repos/$repo/releases/latest" $file; $j=Get-Content $file -Raw|ConvertFrom-Json; $pattern=if($s -eq 'cli-proxy-api'){'_windows_amd64\.zip$'}else{'_windows_amd64\.zip$'}; $asset=$j.assets|? name -match $pattern|select -First 1; $sum=$j.assets|? name -eq 'checksums.txt'|select -First 1; if(!$asset -or !$sum){throw 'Windows x64 asset or checksums.txt missing.'}; @($asset.browser_download_url,$sum.browser_download_url,$asset.name) }
function Install-VerifiedRelease([string]$Service) { $s=Resolve-CPAService $Service; $r=Get-CPAStackRoot; $i=Get-ReleaseInfo $s; $zip=Join-Path $r "downloads\$($i[2])"; $sum=Join-Path $r "downloads\$s-checksums.txt"; Invoke-CPAStackWeb $i[0] $zip; Invoke-CPAStackWeb $i[1] $sum; $hash=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLower(); if((Get-Content $sum|? {$_ -match [regex]::Escape($i[2]) -and $_ -match $hash}).Count -ne 1){throw 'Checksum verification failed.'}; $version=($i[2] -replace '.*_v?([0-9]+(\.[0-9]+)+)_.*','$1'); $dest=Join-Path $r "releases\$s\$version"; if(!(Test-Path $dest)){Expand-Archive $zip $dest -Force}; $bin=if($s -eq 'cli-proxy-api'){'cli-proxy-api.exe'}else{'cpa-usage-keeper.exe'}; $exe=Get-ChildItem $dest -Recurse -Filter $bin|select -First 1; if(!$exe){throw 'Release binary missing.'}; if($exe.DirectoryName -ne $dest){Move-Item $exe.FullName (Join-Path $dest $bin) -Force}; $cur=Join-Path $r "current\$s"; if(Test-Path $cur){Remove-Item $cur -Force}; cmd /c "mklink /J `"$cur`" `"$dest`""|Out-Null; $version }
